/** object.next : u8  at Scanned
 * size=Fixed(1) align=Unaligned repr=MemoryIdentical atomic=AtomicWord mutate=InPlaceFixed
 *
 * The bytes that may stand in front of `next`: ' ' '\\t' '\\r' '\\n'.
 *
 * They are the member's own, so the struct still partitions its
 * bytes exactly -- what the lead costs is the offset, which is
 * a scan from here on rather than a number.
 */
static const uint8_t fzn_json_object_next_lead_set[4] = {0x20u, 0x09u, 0x0Du, 0x0Au};

static inline uint32_t fzn_json_object_next_lead_from(situ_view_t view, uint32_t at)
{
	return situ_skip(situ_base(view) + at, situ_remaining_u32(view.limit, at), fzn_json_object_next_lead_set, 4u);
}
static inline uint32_t fzn_json_object_next_start(situ_view_t view)
{
	uint32_t offset = 1u;
	(void)view;

	return offset;
}

/** Past the whitespace, which is where `next`
 * actually starts. Saturating like every other term: a lead
 * that runs to the end of the view leaves the member outside
 * it, and the accessors' own bounds check is what reports that.
 */
