{
	uint32_t offset = 1u;
	offset = situ_advance_u32(offset, (fzn_json_object_next_stride_from(view, offset)), view.limit);

	return offset;
}
static inline situ_err_t fzn_json_object_body_as_empty_view(situ_view_t view, situ_view_t *out)
{
	if (fzn_json_object_next_get(view) != 125u) {
		return SITU_ERR_VERSION;
	}
	return situ_view_sub(view, fzn_json_object_body_as_empty_offset(view), FZN_JSON_CLOSED_SIZE_FIXED, out);
}

