/** How many bytes one `object` occupies at this view's base.
 *
 * A run of these is walked rather than indexed, and the walk needs
 * to know where each one ends. For a struct whose own members are
 * delimited that is a scan, not a constant.
 */
static inline uint32_t fzn_json_object_extent_at(situ_view_t view, uint32_t depth)
{
	uint32_t extent = 1u;

	if (depth >= 65u) {
		return view.limit;	/* `[depth]`/`[limit]`: the rest (26.1127) */
	}
	if (!situ_in_bounds(view, 0u, 1u)) {
		return 1u;	/* the lengths below are not here to read */
	}
	extent = extent + (fzn_json_object_next_stride(view));
	extent = extent + ((fzn_json_object_next_get(view) == 125u ? 1u : (fzn_json_object_body_as_members_extent_at(view, depth))));
	return extent;
}

