/** How deep this `object` nests, capped at 66.
 *
 * Capped so it terminates on any input, and one above the
 * bound THIS BUILD ENFORCES -- not the declared depth, which
 * this said until a schema stated `[depth]` and `[limit]`
 * separately and the two stopped being one number. A probe
 * that saturated at the bound could not tell a conforming
 * message from a violating one.
 */
static inline uint32_t fzn_json_object_nesting_at(situ_view_t view, uint32_t depth);
static inline uint32_t fzn_json_object_nesting_at(situ_view_t view, uint32_t depth)
{
	uint32_t deepest = depth;

	if (depth > 65u) {
		return depth;	/* capped: past here the answer is "too deep" */
	}
	if (!situ_in_bounds(view, 0u, 1u)) {
		return depth;	/* nothing here to descend into */
	}
	{
		situ_view_t element;

		if (fzn_json_object_body_as_members_offset(view) < view.limit && situ_view_sub(view, fzn_json_object_body_as_members_offset(view), situ_remaining_u32(view.limit, fzn_json_object_body_as_members_offset(view)), &element) == SITU_OK
				&& (fzn_json_object_next_get(view) != 125u)
				) {
			const uint32_t found = fzn_json_members_nesting_at(element, depth + 1u);

			if (found > deepest) {
				deepest = found;
				if (deepest > 65u) {
					return deepest;	/* too deep: nothing further changes that */
				}
			}
		}
	}
	return deepest;
}

static inline uint32_t fzn_json_object_nesting(situ_view_t view)
{
	return fzn_json_object_nesting_at(view, 0u);
}

/** How many bytes a whole `object` needs, given `have` of them.
 *
 * SITU_OK            a complete one is present; *need is its length
 * SITU_ERR_TRUNCATED not yet; *need is a lower bound on the total
 *
 * For framing a stream: read, ask, read the difference, ask again. The
 * length fields are read only once the bytes holding them have arrived,
 * which is the case every hand-written version of this gets wrong.
 *
 * SITU_ERR_CONSTRAINT nested past its bound, which no more bytes mend
 */
static inline situ_err_t fzn_json_object_required_at(const uint8_t *data, uint32_t have, uint32_t *need, uint32_t depth)
{
	uint32_t at = 1u;
	uint32_t pos = 1u;
	situ_view_t view;

	/* `object` nests at most 64 deep, and each level
	 * is a call: past the bound the message is refused, which no
	 * further byte can change, and the stack stays bounded (20.1). */
	if (depth > 64u) {
		*need = have;
		return SITU_ERR_CONSTRAINT;
	}
	/* A view over what has arrived, so every length expression below
	 * reads through the same bounds the accessors do. */
	view.base       = (uint8_t *)(uintptr_t)(const void *)data;
	view.limit      = have;
	view.generation = 0u;
	view.owner      = NULL;

	/* object.next: reading its length means reading bytes that
	 * have to be here first. */
	if (have < pos) {
		*need = at;
		return SITU_ERR_TRUNCATED;
	}
	{
		const uint32_t len = fzn_json_object_next_stride_from(view, pos);

		at = situ_need_u32(at, len);
		pos = situ_need_u32(pos, len);
	}

	/* object.body: reading its length means reading bytes that
	 * have to be here first. */
	if (have < pos) {
		*need = at;
		return SITU_ERR_TRUNCATED;
	}

	/* object.body: the arm the discriminant selects frames
	 * itself. Its EXTENT shrinks when the bytes run out, so
	 * adding that reported a complete message -- reported by
	 * bbq-predictor against a variant arm (26.684). */
	{
		uint32_t   part = 0u;
		situ_err_t e = SITU_OK;

		if (have < situ_need_u32(pos, 1u)) {
			*need = situ_need_u32(pos, 1u) > at ? situ_need_u32(pos, 1u) : at;
			return SITU_ERR_TRUNCATED;
		}
		if (fzn_json_object_next_get(view) == 125u) {
			e = fzn_json_closed_required(data + pos,
			                situ_remaining_u32(have, pos), &part);
			if (e != SITU_OK) {
				*need = situ_need_u32(at, part);
				return SITU_ERR_TRUNCATED;
			}
		} else {
			e = fzn_json_members_required_at(data + pos,
			                situ_remaining_u32(have, pos), &part, depth + 1u);
			if (e == SITU_ERR_CONSTRAINT || e == SITU_ERR_DEPTH) {
				*need = have;
				return e;
			}
			if (e != SITU_OK) {
				*need = situ_need_u32(at, part);
				return SITU_ERR_TRUNCATED;
			}
		}
		(void)e;
		at = situ_need_u32(at, part);
	}

	*need = at;
	return have >= at ? SITU_OK : SITU_ERR_TRUNCATED;
}

